import SwiftUI
import CoreMotion

/// Flowing silk background. Copy `Silk.metal` alongside this file.
/// The shader samples the fold height field three times to build a normal, then shades it with Blinn-Phong so the sheen sits on the folds facing the light.
///
/// - Parameters:
///   - style: Fabric color, sheen color, fold contrast and highlight tightness. `.standard` (default) follows light and dark; `.tangerine`, `.sky`, `.butter`, `.sage`, `.lilac` and `.sand` are solid house-block fabrics for panels and cards. `.ink`, `.graphite`, `.paper` and `.indigo` remain available.
///   - light: Where the light comes from, in unit coordinates of the view. Top-left by default.
///   - tiltLight: When true, the device's attitude moves the light. Uses Core Motion and stops whenever the scene is not active.
///   - scale: Pattern zoom; larger is finer folds.
///   - speed: Time multiplier.
public struct Silk: View {
    /// Material recipe for the fabric.
    public struct Style: Sendable {
        public var tint: Color
        public var sheen: Color
        /// How dark the shadowed side of a fold gets, 0–1.
        public var depth: Float
        /// Specular exponent; higher is a tighter, glossier highlight.
        public var shine: Float

        public init(tint: Color, sheen: Color, depth: Float = 0.5, shine: Float = 24) {
            self.tint = tint
            self.sheen = sheen
            self.depth = depth
            self.shine = shine
        }

        // MARK: House styles

        /// Stone fabric with a white sheen in light; charcoal with a sand sheen in dark.
        public static let standard = Style(tint: silkColor(light: 0xE7E4DC, dark: 0x1C1C1C), sheen: silkColor(light: 0xFFFFFF, dark: 0xE9D5B3), depth: 0.42, shine: 26)
        /// Solid tangerine block fabric. Put `#141414` ink on it.
        public static let tangerine = Style.block(0xFF5B3A)
        /// Solid sky block fabric. Put `#141414` ink on it.
        public static let sky = Style.block(0x9CC2FF)
        /// Solid butter block fabric. Put `#141414` ink on it.
        public static let butter = Style.block(0xFFD976)
        /// Solid sage block fabric. Put `#141414` ink on it.
        public static let sage = Style.block(0xA9DCB7)
        /// Solid lilac block fabric. Put `#141414` ink on it.
        public static let lilac = Style.block(0xCDB8FF)
        /// Solid sand block fabric. Put `#141414` ink on it.
        public static let sand = Style.block(0xE9D5B3)

        private static func block(_ hex: UInt32) -> Style {
            Style(tint: silkColor(hex), sheen: silkColor(0xFFFFFF), depth: 0.3, shine: 22)
        }

        // MARK: Earlier styles

        public static let ink = Style(tint: Color(red: 0.09, green: 0.10, blue: 0.14), sheen: Color(red: 0.55, green: 0.60, blue: 0.75), depth: 0.5, shine: 24)
        public static let graphite = Style(tint: Color(red: 0.16, green: 0.16, blue: 0.17), sheen: Color(red: 0.72, green: 0.72, blue: 0.74), depth: 0.45, shine: 20)
        public static let paper = Style(tint: Color(red: 0.91, green: 0.90, blue: 0.87), sheen: .white, depth: 0.16, shine: 32)
        public static let indigo = Style(tint: Color(red: 0.30, green: 0.27, blue: 0.78), sheen: Color(red: 0.86, green: 0.82, blue: 1.0), depth: 0.55, shine: 28)
    }

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Environment(\.scenePhase) private var scenePhase
    @State private var tilt = TiltSource()

    private let style: Style
    private let light: UnitPoint
    private let tiltLight: Bool
    private let scale: Float
    private let speed: Double

    public init(style: Style = .standard, light: UnitPoint = UnitPoint(x: 0.3, y: 0.2), tiltLight: Bool = false, scale: Float = 2, speed: Double = 1) {
        self.style = style
        self.light = light
        self.tiltLight = tiltLight
        self.scale = scale
        self.speed = speed
    }

    public var body: some View {
        TimelineView(.animation(paused: reduceMotion && !tiltLight)) { context in
            let time = Float(context.date.timeIntervalSinceReferenceDate.truncatingRemainder(dividingBy: 3600) * (reduceMotion ? 0 : speed))
            let lightPoint = CGPoint(
                x: light.x + (tiltLight ? tilt.offset.x : 0),
                y: light.y + (tiltLight ? tilt.offset.y : 0)
            )
            Rectangle()
                .visualEffect { content, proxy in
                    content.colorEffect(
                        ShaderLibrary.silk(
                            .float2(proxy.size),
                            .float(time),
                            .color(style.tint),
                            .color(style.sheen),
                            .float(scale),
                            .float2(lightPoint),
                            .float(style.depth),
                            .float(style.shine)
                        )
                    )
                }
        }
        .ignoresSafeArea()
        .accessibilityHidden(true)
        .onAppear { if tiltLight, scenePhase == .active { tilt.start() } }
        .onDisappear { tilt.stop() }
        .onChange(of: scenePhase) { _, phase in
            if phase == .active, tiltLight { tilt.start() } else { tilt.stop() }
        }
    }
}

/// Low-passed device attitude, mapped to a light offset in unit coordinates. Runs only while started.
@MainActor @Observable private final class TiltSource {
    private(set) var offset = CGPoint.zero
    @ObservationIgnored private let manager = CMMotionManager()
    @ObservationIgnored private var reference: (roll: Double, pitch: Double)?

    nonisolated init() {}

    func start() {
        guard !manager.isDeviceMotionActive, manager.isDeviceMotionAvailable else { return }
        manager.deviceMotionUpdateInterval = 1 / 30
        manager.startDeviceMotionUpdates(to: .main) { [weak self] motion, _ in
            guard let motion else { return }
            let roll = motion.attitude.roll
            let pitch = motion.attitude.pitch
            Task { @MainActor in self?.push(roll: roll, pitch: pitch) }
        }
    }

    func stop() {
        manager.stopDeviceMotionUpdates()
        reference = nil
        offset = .zero
    }

    private func push(roll: Double, pitch: Double) {
        // Measure relative to the attitude at start so a reclined phone still lights from the configured point.
        let reference = reference ?? (roll, pitch)
        self.reference = reference
        let target = CGPoint(
            x: min(max((roll - reference.roll) * 0.6, -0.6), 0.6),
            y: min(max((pitch - reference.pitch) * 0.6, -0.6), 0.6)
        )
        offset = CGPoint(x: offset.x + (target.x - offset.x) * 0.15, y: offset.y + (target.y - offset.y) * 0.15)
    }
}

/// A solid sRGB color from a hex value.
private func silkColor(_ hex: UInt32) -> Color {
    Color(uiColor: silkUIColor(hex))
}

/// A color that resolves to `light` or `dark` with the current appearance.
private func silkColor(light: UInt32, dark: UInt32) -> Color {
    let l = silkUIColor(light), d = silkUIColor(dark)
    return Color(uiColor: UIColor { $0.userInterfaceStyle == .dark ? d : l })
}

private func silkUIColor(_ hex: UInt32) -> UIColor {
    UIColor(red: CGFloat((hex >> 16) & 0xFF) / 255, green: CGFloat((hex >> 8) & 0xFF) / 255, blue: CGFloat(hex & 0xFF) / 255, alpha: 1)
}

// MARK: - Example

/// The fabric, full bleed, with nothing on top of it. `.tangerine` is used because the folds and the sheen read on a
/// solid house block the way silk reads on a bolt of cloth.
private struct SilkExample: View {
    var body: some View {
        Silk(style: .tangerine, scale: 2.6)
            .ignoresSafeArea()
    }
}

#Preview("Light") {
    SilkExample().preferredColorScheme(.light)
}

#Preview("Dark") {
    SilkExample().preferredColorScheme(.dark)
}

import SwiftUI

/// Interactive dot grid. Resting dots are a tonal ramp on `Style.dot` (`.primary` by default, so both color schemes work);
/// under the finger they swell and take on `Style.highlight`, a solid house block.
///
/// - Parameters:
///   - spacing: Distance between dots.
///   - dotSize: Resting dot diameter.
///   - radius: Influence radius of the touch.
///   - baseOpacity: Opacity of resting dots on `.primary`.
///   - ripples: Whether a tap emits a ripple ring. Reduce Motion disables ripples regardless.
///   - probe: Optional programmatic touch point for previews and onboarding hints. Setting it back to `nil` triggers the release spring; a probe held under 0.3 s emits a ripple like a tap.
///   - style: Resting dot color and the block color dots take on under the finger. `.standard` (default) warms into tangerine; `.sky`, `.lilac`, `.sage` and `.butter` use the other blocks; `.mono` keeps the original single-tone ramp.
public struct TouchGrid: View {
    /// Dot colors.
    public struct Style: Sendable {
        /// Resting dot color; `baseOpacity` is applied on top.
        public var dot: Color
        /// Color the dots blend into as they lift under the finger and in ripples.
        public var highlight: Color

        public init(dot: Color = .primary, highlight: Color) {
            self.dot = dot
            self.highlight = highlight
        }

        /// Tangerine under the finger.
        public static let standard = Style(highlight: touchGridColor(0xFF5B3A))
        /// Sky under the finger.
        public static let sky = Style(highlight: touchGridColor(0x9CC2FF))
        /// Lilac under the finger.
        public static let lilac = Style(highlight: touchGridColor(0xCDB8FF))
        /// Sage under the finger.
        public static let sage = Style(highlight: touchGridColor(0xA9DCB7))
        /// Butter under the finger.
        public static let butter = Style(highlight: touchGridColor(0xFFD976))
        /// The single-tone ramp on `.primary`.
        public static let mono = Style(highlight: .primary)
    }

    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    @State private var touch: CGPoint? = nil
    @State private var touchStart: Date? = nil
    @State private var release: Release? = nil
    @State private var ripples: [Ripple] = []
    @State private var cell = -1
    @State private var lastTick = Date.distantPast
    @State private var settleToken = 0

    private let spacing: CGFloat
    private let dotSize: CGFloat
    private let radius: CGFloat
    private let baseOpacity: Double
    private let ripplesEnabled: Bool
    private let probe: CGPoint?
    private let style: Style

    private struct Release { let point: CGPoint; let date: Date }
    private struct Ripple: Identifiable { let id = UUID(); let center: CGPoint; let date: Date }

    private let releaseDuration: TimeInterval = 0.55
    private let rippleDuration: TimeInterval = 1.1

    public init(
        spacing: CGFloat = 24,
        dotSize: CGFloat = 3,
        radius: CGFloat = 120,
        baseOpacity: Double = 0.18,
        ripples: Bool = true,
        probe: CGPoint? = nil,
        style: Style = .standard
    ) {
        self.style = style
        self.spacing = spacing
        self.dotSize = dotSize
        self.radius = radius
        self.baseOpacity = baseOpacity
        self.ripplesEnabled = ripples
        self.probe = probe
    }

    private var active: Bool { touch != nil || release != nil || !ripples.isEmpty }

    public var body: some View {
        TimelineView(.animation(paused: !active)) { context in
            let now = context.date
            Canvas(rendersAsynchronously: true) { graphics, size in
                draw(in: &graphics, size: size, now: now)
            }
        }
        .contentShape(Rectangle())
        .gesture(drag)
        .sensoryFeedback(.selection, trigger: cell) { old, new in old >= 0 && new >= 0 }
        .onChange(of: probe) { _, point in
            // A probe held under 0.3 s counts as a tap, mirroring the finger rule.
            if let point { press(at: point) } else if touch != nil { lift(tapped: touchStart.map { Date().timeIntervalSince($0) < 0.3 } ?? false) }
        }
        .onAppear { if let probe { press(at: probe) } }
        // Once the last spring and ripple have played out, clear them so the timeline can pause.
        .task(id: settleToken) {
            try? await Task.sleep(for: .seconds(rippleDuration + 0.1))
            guard !Task.isCancelled else { return }
            release = nil
            ripples.removeAll()
        }
        .accessibilityHidden(true)
    }

    // MARK: Input

    private var drag: some Gesture {
        DragGesture(minimumDistance: 0)
            .onChanged { value in
                press(at: value.location)
                // Low-rate tick when the finger crosses into another grid cell.
                let index = Int(value.location.x / spacing) + Int(value.location.y / spacing) * 4096
                if index != cell, Date().timeIntervalSince(lastTick) > 0.06 {
                    cell = index
                    lastTick = Date()
                }
            }
            .onEnded { value in
                let moved = hypot(value.translation.width, value.translation.height)
                let held = touchStart.map { Date().timeIntervalSince($0) } ?? 0
                lift(tapped: moved < 8 && held < 0.3)
            }
    }

    private func press(at point: CGPoint) {
        if touch == nil { touchStart = Date() }
        touch = point
        release = nil
    }

    private func lift(tapped: Bool) {
        guard let point = touch else { return }
        release = Release(point: point, date: Date())
        if tapped, ripplesEnabled, !reduceMotion {
            ripples.append(Ripple(center: point, date: Date()))
            if ripples.count > 3 { ripples.removeFirst() }
        }
        touch = nil
        touchStart = nil
        cell = -1
        settleToken += 1
    }

    // MARK: Drawing

    /// Strength of the touch field: 1 while pressed, then a damped spring that dips just below zero before settling.
    private func fieldStrength(now: Date) -> (center: CGPoint, strength: CGFloat)? {
        if let touch { return (touch, 1) }
        guard let release else { return nil }
        let t = now.timeIntervalSince(release.date)
        guard t < releaseDuration else { return nil }
        let s = exp(-7 * t) * cos(10 * t)
        return (release.point, CGFloat(max(s, -0.12)))
    }

    private func draw(in graphics: inout GraphicsContext, size: CGSize, now: Date) {
        let field = fieldStrength(now: now)
        let liveRipples: [(center: CGPoint, progress: CGFloat)] = ripples.compactMap { ripple in
            let t = now.timeIntervalSince(ripple.date) / rippleDuration
            return t < 1 ? (ripple.center, CGFloat(t)) : nil
        }
        let rippleReach = radius * 2.4
        let cols = Int(size.width / spacing) + 1
        let rows = Int(size.height / spacing) + 1

        for row in 0..<rows {
            for col in 0..<cols {
                let p = CGPoint(x: CGFloat(col) * spacing + spacing / 2, y: CGFloat(row) * spacing + spacing / 2)
                var lift: CGFloat = 0

                if let field {
                    let d = hypot(p.x - field.center.x, p.y - field.center.y)
                    let falloff = max(0, 1 - d / radius)
                    lift += falloff * falloff * (3 - 2 * falloff) * field.strength
                }
                for ripple in liveRipples {
                    // Ring front eases outward; the band fades and widens as it travels.
                    let eased = 1 - pow(1 - ripple.progress, 3)
                    let front = eased * rippleReach
                    let d = hypot(p.x - ripple.center.x, p.y - ripple.center.y)
                    let band = spacing * (1.2 + eased * 2)
                    let wave = exp(-pow((d - front) / band, 2)) * (1 - ripple.progress)
                    lift += wave * 0.7
                }

                lift = min(max(lift, -0.12), 1)
                let s = dotSize * (1 + lift * 2.2)
                let rise = max(lift, 0)
                let rect = CGRect(x: p.x - s / 2, y: p.y - s / 2, width: s, height: s)
                let dot = Path(ellipseIn: rect)
                // Resting ink fades out as the block color fades in, so a lifted dot reads as solid highlight.
                graphics.fill(dot, with: .color(style.dot.opacity(baseOpacity * (1 - rise))))
                if rise > 0.01 {
                    graphics.fill(dot, with: .color(style.highlight.opacity(min(1, 0.25 + rise * 0.9))))
                }
            }
        }
    }
}

/// A solid sRGB color from a hex value.
private func touchGridColor(_ hex: UInt32) -> Color {
    Color(uiColor: touchGridUIColor(hex))
}

/// A color that resolves to `light` or `dark` with the current appearance.
private func touchGridColor(light: UInt32, dark: UInt32) -> Color {
    let l = touchGridUIColor(light), d = touchGridUIColor(dark)
    return Color(uiColor: UIColor { $0.userInterfaceStyle == .dark ? d : l })
}

private func touchGridUIColor(_ hex: UInt32) -> UIColor {
    UIColor(red: CGFloat((hex >> 16) & 0xFF) / 255, green: CGFloat((hex >> 8) & 0xFF) / 255, blue: CGFloat(hex & 0xFF) / 255, alpha: 1)
}

