        ZStack {
            GlassTextPalette.sky.ignoresSafeArea()
            Circle()
                .fill(GlassTextPalette.tangerine)
                .frame(width: 190)
                .offset(x: -70 + drift * 46, y: 8 + CGFloat(cos(t * 0.35)) * 14)
